{ pkgs ? import <nixpkgs> { }, lib ? pkgs.lib, ... }:
let
  inherit (pkgs.callPackage ./. { }) findCrates;

  cargoMembersTest = {
    testStar = {
      expr = findCrates [ "crates/*" ] ./test;
      expected = [ "crates/crate-a" ];
    };

  };
  # Like lib.runTests, but actually fails if any test fails.
  runTestsFailing = tests:
    let
      res = lib.runTests tests;
    in
    if res == builtins.trace "✅ All tests passed" [ ]
    then res
    else builtins.throw "Some tests failed: ${builtins.toJSON res}" res;
in
{
  "cargo.members" = runTestsFailing cargoMembersTest;
}

{
  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/nixpkgs-unstable";
    flake-parts.url = "github:hercules-ci/flake-parts";
    crate-parser = { flake = false; }; # Overriden by omci (see top-level flake.nix)
  };
  outputs = inputs:
    inputs.flake-parts.lib.mkFlake { inherit inputs; } {
      systems = inputs.nixpkgs.lib.systems.flakeExposed;
      perSystem = { pkgs, lib, ... }: {
        checks.tests =
          let
            result = import (inputs.crate-parser + /parser_tests.nix) { inherit pkgs lib; };
          in
          pkgs.writeTextFile {
            name = "crate-parsers-test-results";
            text = builtins.toJSON result;
          };
      };
    };
}

use clap::Parser;

#[derive(Parser)]
#[command(name = "hello-world")]
#[command(about = "A simple Hello World CLI application")]
struct Cli {
    /// Name to greet
    #[arg(short, long, default_value = "World")]
    name: String,

    /// Number of times to greet
    #[arg(short, long, default_value_t = 1)]
    count: u8,
}

fn main() {
    let cli = Cli::parse();

    for i in 1..=cli.count {
        if cli.count > 1 {
            println!("{}. Hello, {}!", i, cli.name);
        } else {
            println!("Hello, {}!", cli.name);
        }
    }
}

pub fn a_hello() -> String {
    format!("A says: {}", crate_b::b_hello())
}

pub fn b_hello() -> String {
    format!("B says: {}", crate_c::c_hello())
}

pub fn c_hello() -> String {
    // To avoid infinite recursion, just return a message (do not call crate_a::a_hello())
    "Hello from C!".to_string()
}
